INSERT INTO `wp_options` VALUES (8124,'rank_math_notifications','a:2:{i:0;a:2:{s:7:\"message\";s:1225:\"<p><strong>تصنيف محتواك بقوة الاحتراف والذكاء الاصطناعي.</strong></p><ul>\n								<li>مواقع غير محدودة</li>\n								<li>محتوى الذكاء الاصطناعي. (الذكاء الاصطناعي)</li>\n								<li>تعقب ترتيب الكلمات الرئيسية</li>\n								<li>مولد مخطط قوي</li>\n								<li>الدعم المميّز على مدار الساعة 24 ساعة في اليوم و 7 أيام في الأسبوع 24x7</li>\n								<li>تقارير البريد الإلكتروني لتحسين محركات البحث</li>\n								<li>والمزيد من ذلك...</li>\n							</ul><p>\n								<a href=\"https://rankmath.com/pricing/?utm_source=Plugin&utm_medium=Upgrade%20Notice%202%20New%20Yes&utm_campaign=WP\" class=\"button rank-math-dismiss-pro-notice rank-math-upgrade-action\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>نعم، أرغب في تعلم المزيد</strong></a><a href=\"#\" class=\"rank-math-dismiss-pro-notice rank-math-already-upgraded-action\">لا، لا أريدها</a><a href=\"#\" class=\"rank-math-dismiss-pro-notice rank-math-already-upgraded-action\">لقد قمت بالترقية بالفعل</a>\n							</p>\";s:7:\"options\";a:5:{s:2:\"id\";s:20:\"rank_math_pro_notice\";s:7:\"classes\";s:16:\"rank-math-notice\";s:4:\"type\";s:4:\"info\";s:6:\"screen\";s:3:\"any\";s:10:\"capability\";s:15:\"install_plugins\";}}i:1;a:2:{s:7:\"message\";s:363:\"اكتشفت Rank Math أنواع محتوى جديدة: <code>product</code>, <code>jkit-header</code>, <code>jkit-footer</code>, <code>jkit-template</code>. قد ترغب في التحقق من إعدادات صفحة <a href=\"http://miras-store.local/wp-admin/admin.php?page=rank-math-options-titles&view=post-type-product\">العناوين والميتا</a>.\";s:7:\"options\";a:5:{s:2:\"id\";s:13:\"new_post_type\";s:7:\"classes\";s:16:\"rank-math-notice\";s:4:\"type\";s:4:\"info\";s:6:\"screen\";s:3:\"any\";s:10:\"capability\";s:0:\"\";}}}','auto');
