INSERT INTO `wp_posts` VALUES (834,1,'2026-09-13 14:23:19','2026-09-13 14:23:19','<!-- wp:heading {\"level\":1,\"textAlign\":\"center\"} -->\n<h1 style=\"margin-bottom: 20px; font-size: 42px; color: #1b4332;\">انضم كبائع موثّق في مِراس</h1>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p style=\"font-size: 18px; color: #555; max-width: 800px; margin: 0 auto 50px;\">هل أنت منتج أو حرفي يمني؟ انضم إلى مجتمع مِراس واعرض منتجاتك التراثية والأصيلة لآلاف المشترين المهتمين. نحن نوفر لك المنصة، وأنت توفر الإبداع!</p>\n<!-- /wp:paragraph --><!-- wp:heading {\"level\":2,\"textAlign\":\"center\"} -->\n<h2 style=\"margin-bottom: 30px; color: #2d6a4f;\">لماذا تبيع منتجاتك معنا؟</h2>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column -->\n<h3 style=\"color: #1b4332; margin-bottom: 15px;\">الوصول لآلاف العملاء</h3>\n<p style=\"color: #666;\">منصتنا تستقطب يومياً آلاف الزوار المهتمين بالمنتجات التراثية، مما يضمن لك مبيعات أعلى وانتشاراً أوسع.</p>\n<!-- /wp:column --><!-- wp:column -->\n<h3 style=\"color: #1b4332; margin-bottom: 15px;\">مدفوعات آمنة ومضمونة</h3>\n<p style=\"color: #666;\">نتولى عنك عمليات الدفع الإلكتروني وتحصيل الأموال بأمان تام، مع تحويل أرباحك بشكل دوري وسريع.</p>\n<!-- /wp:column --><!-- wp:column -->\n<h3 style=\"color: #1b4332; margin-bottom: 15px;\">دعم تسويقي وتقني</h3>\n<p style=\"color: #666;\">فريقنا يساعدك في تسويق منتجاتك وتصويرها (إن لزم الأمر)، ويوفر لك لوحة تحكم سهلة لإدارة متجرك.</p>\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:heading {\"level\":2,\"textAlign\":\"center\"} -->\n<h2 style=\"margin-bottom: 30px; color: #2d6a4f;\">كيف تبدأ رحلتك كبائع؟</h2>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"width\":\"33.33%\"} -->\n1\n<h4 style=\"color: #333;\">سجل بياناتك</h4>\n<p style=\"font-size: 14px; color: #777;\">قم بتعبئة النموذج أدناه بمعلوماتك الشخصية وتفاصيل منتجاتك.</p>\n<!-- /wp:column --><!-- wp:column {\"width\":\"33.33%\"} -->\n2\n<h4 style=\"color: #333;\">موافقة الإدارة</h4>\n<p style=\"font-size: 14px; color: #777;\">سيقوم فريقنا بمراجعة طلبك والتواصل معك لتوثيق حسابك وفتح متجرك.</p>\n<!-- /wp:column --><!-- wp:column {\"width\":\"33.33%\"} -->\n3\n<h4 style=\"color: #333;\">أضف وبِع!</h4>\n<p style=\"font-size: 14px; color: #777;\">ابدأ بإضافة منتجاتك وصورك الخاصة، واستقبل طلبات العملاء فوراً.</p>\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:heading {\"level\":2,\"textAlign\":\"center\"} -->\n<h2 style=\"margin-bottom: 20px; color: #2d6a4f;\">نموذج طلب الانضمام كبائع</h2>\n<!-- /wp:heading --><!-- wp:html -->\n<form style=\"display: flex; flex-direction: column; gap: 20px; direction: rtl;\" action=\"\" method=\"post\">\n<label style=\"display: block; margin-bottom: 8px; font-weight: 600; color: #333;\">الاسم الرباعي *</label> <input style=\"width: 100%; padding: 14px; border: 1px solid #ddd; border-radius: 8px; font-size: 15px; background: #fdfdfd; font-family: inherit;\" name=\"seller_name\" required=\"\" type=\"text\" placeholder=\"أدخل اسمك الكامل\" />\n<label style=\"display: block; margin-bottom: 8px; font-weight: 600; color: #333;\">رقم الجوال (واتساب) *</label> <input style=\"width: 100%; padding: 14px; border: 1px solid #ddd; border-radius: 8px; font-size: 15px; background: #fdfdfd; font-family: inherit; direction: ltr; text-align: right;\" name=\"seller_phone\" required=\"\" type=\"tel\" placeholder=\"+967 7x xxx xxxx\" />\n<label style=\"display: block; margin-bottom: 8px; font-weight: 600; color: #333;\">البريد الإلكتروني *</label> <input style=\"width: 100%; padding: 14px; border: 1px solid #ddd; border-radius: 8px; font-size: 15px; background: #fdfdfd; font-family: inherit;\" name=\"seller_email\" required=\"\" type=\"email\" placeholder=\"example@email.com\" />\n<label style=\"display: block; margin-bottom: 8px; font-weight: 600; color: #333;\">اسم المتجر أو العلامة التجارية *</label> <input style=\"width: 100%; padding: 14px; border: 1px solid #ddd; border-radius: 8px; font-size: 15px; background: #fdfdfd; font-family: inherit;\" name=\"store_name\" required=\"\" type=\"text\" placeholder=\"اسم متجرك المقترح\" />\n<label style=\"display: block; margin-bottom: 8px; font-weight: 600; color: #333;\">نوع المنتجات التي تبيعها *</label><select style=\"width: 100%; padding: 14px; border: 1px solid #ddd; border-radius: 8px; font-size: 15px; background: #fdfdfd; font-family: inherit;\" name=\"product_type\" required=\"\">\n<option value=\"\">اختر التصنيف...</option>\n<option value=\"honey\">عسل يمني</option>\n<option value=\"coffee\">بن يمني</option>\n<option value=\"spices\">بهارات ومكسرات</option>\n<option value=\"handicrafts\">حرف يدوية وفضيات</option>\n<option value=\"clothes\">أزياء وتراثيات</option>\n<option value=\"other\">أخرى</option>\n</select>\n<label style=\"display: block; margin-bottom: 8px; font-weight: 600; color: #333;\">نبذة عن منتجاتك وتفاصيل أخرى (اختياري)</label> <textarea style=\"width: 100%; padding: 14px; border: 1px solid #ddd; border-radius: 8px; font-size: 15px; background: #fdfdfd; font-family: inherit; resize: vertical;\" name=\"seller_notes\" rows=\"4\" placeholder=\"حدثنا أكثر عن جودة منتجاتك ومصدرها...\"></textarea>\n<button style=\"background: #1b4332; color: #fff; padding: 16px; border: none; border-radius: 8px; font-size: 18px; font-weight: bold; cursor: pointer; font-family: inherit; transition: background 0.3s; margin-top: 10px;\" type=\"submit\">إرسال طلب الانضمام</button></form>\n<!-- /wp:html --><!-- wp:heading {\"level\":2,\"textAlign\":\"center\"} -->\n<h2 style=\"margin-bottom: 30px; color: #2d6a4f;\">أسئلة شائعة للبائعين</h2>\n<!-- /wp:heading --><!-- wp:details --><details style=\"max-width: 800px; margin: 0 auto 15px; border: 1px solid #eaeaea; padding: 15px; border-radius: 8px; background: #fff;\">\n<summary style=\"font-weight: bold; color: #333; font-size: 16px; cursor: pointer;\">هل توجد رسوم للتسجيل كبائع؟</summary>\n<!-- wp:paragraph -->\n<p style=\"margin-top: 10px; color: #666; line-height: 1.6;\">لا، التسجيل وفتح متجرك وعرض منتجاتك مجاني بالكامل. نحن نأخذ فقط عمولة بسيطة ومناسبة يتم الاتفاق عليها مسبقاً عند كل عملية بيع ناجحة.</p>\n<!-- /wp:paragraph --></details><!-- /wp:details --><!-- wp:details --><details style=\"max-width: 800px; margin: 0 auto 15px; border: 1px solid #eaeaea; padding: 15px; border-radius: 8px; background: #fff;\">\n<summary style=\"font-weight: bold; color: #333; font-size: 16px; cursor: pointer;\">كيف يتم شحن منتجاتي للعملاء؟</summary>\n<!-- wp:paragraph -->\n<p style=\"margin-top: 10px; color: #666; line-height: 1.6;\">نحن في مِراس نتعاون مع أفضل شركات الشحن. عند استلامك لطلب، ستقوم بتجهيزه، وسيقوم مندوب الشحن الخاص بنا باستلامه من موقعك وتوصيله للعميل.</p>\n<!-- /wp:paragraph --></details><!-- /wp:details -->','كن بائعاً','','inherit','closed','closed','','25-autosave-v1','','','2026-09-13 14:23:19','2026-09-13 14:23:19','',25,'http://miras-store.local/?p=834',0,'revision','',0);
